import{z as B,x as s,o as e,c as d,q as E,j as n,D as r,d as o,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"前馈与反馈 run-to-run","description":"","frontmatter":{"title":"前馈与反馈 run-to-run","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/feedforward-feedback-r2r.md","filePath":"litho/feedforward-feedback-r2r.md","lastUpdated":1791413859000}'),p={name:"litho/feedforward-feedback-r2r.md"};function A(u,a,m,h,_,f){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=E('<h1 id="前馈与反馈-run-to-run" tabindex="-1">前馈与反馈 run-to-run <a class="header-anchor" href="#前馈与反馈-run-to-run" aria-label="Permalink to &quot;前馈与反馈 run-to-run&quot;">​</a></h1><div class="epigraph"><p>前馈用已经量到的上游扰动去改本步设定；反馈用本步结果去改下一步。Run-to-run 把两者收成批与批之间的控制器，而不是片内毫秒环。</p><footer>—— 对照 Moyne 等对半导体 run-to-run 控制的论述；SEMI 对 R2R 的通称</footer></div><p><a href="/litho/apc">上一课</a>给出厂级控制器骨架。缺口是信息方向：胶厚已经量了，还要不要等本层 CD 回来再补？本课钉前馈与反馈的 R2R。抽样计划决定这些环看见什么，留给<a href="/litho/sampling-plan">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前馈例子：涂胶后测厚度 → 改扫描机剂量；CMP 后厚度图 → 改焦点地图；刻蚀前开口率 → 改过刻。反馈例子：本批 ADI CD → 下批剂量；本批套刻 → 下批网格。前馈快、不消耗本层返工，但依赖上游计量与模型；反馈慢、能纠正模型误差，但已经曝光的片救不回。</p>',5)),(e(),n(i,null,{default:r(()=>[l(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20FFLOOP%5B%22%E5%89%8D%E9%A6%88%EF%BC%9A%E5%90%8C%E4%B8%80%E6%89%B9%E5%86%85%E8%B5%B7%E4%BD%9C%E7%94%A8%22%5D%0A%20%20%20%20A0%5B%22%E6%B6%82%E8%83%B6%E5%90%8E%E6%B5%8B%E8%83%B6%E5%8E%9A%22%5D%20--%3E%20A1%5B%22%E7%AB%8B%E5%88%BB%E6%94%B9%E6%9C%AC%E6%89%B9%E5%89%82%E9%87%8F%22%5D%0A%20%20%20%20A1%20--%3E%20A2%5B%22%E6%9C%AC%E6%89%B9%E6%9B%9D%E5%85%89%22%5D%0A%20%20end%0A%20%20subgraph%20FBLOOP%5B%22%E5%8F%8D%E9%A6%88%EF%BC%9A%E6%89%B9%E4%B8%8E%E6%89%B9%E4%B9%8B%E9%97%B4%E8%B5%B7%E4%BD%9C%E7%94%A8%22%5D%0A%20%20%20%20B0%5B%22%E6%9C%AC%E6%89%B9%E6%9B%9D%E5%85%89%22%5D%20--%3E%20B1%5B%22%E9%87%8F%E6%9C%AC%E6%89%B9%20CD%20%2F%20%E5%A5%97%E5%88%BB%22%5D%0A%20%20%20%20B1%20--%3E%20B2%5B%22%E6%94%B9%E4%B8%8B%E4%B8%80%E6%89%B9%E8%AE%BE%E5%AE%9A%22%5D%0A%20%20end%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>这张图回答的问题是：前馈和反馈各自在哪个节拍上起作用。前馈在片还没曝光之前就把修正加进去；反馈必须等本批量完，只能作用于下一批——这个节拍差决定了两条环的延迟模型完全不同。</p><p><span class="marginnote">直觉类比：前馈像导航看到前方三公里堵车、立刻改道，堵车还没轮到你；反馈像已经堵在路上，只能根据当前车速一点点调。前馈救「还没发生的错」，反馈防「已经犯过的错再犯一次」。</span></p><p>缺口是<strong>不要两条环抢同一个旋钮</strong>。厚度前馈已经加了剂量，CD 反馈再加一刀，会振荡。状态要共享或分层：前馈改预期，反馈只吃残差。</p><h3 id="run-to-run-不是片内" tabindex="-1">Run-to-run 不是片内 <a class="header-anchor" href="#run-to-run-不是片内" aria-label="Permalink to &quot;Run-to-run 不是片内&quot;">​</a></h3><p>扫描机剂量传感器是片内/脉冲级。R2R 的节拍是批、或若干片。把 R2R 增益调成片内，计量延迟会让控制器打自己。YieldStar 或独立套刻机的延迟必须以节拍建模。</p><p><span class="marginnote">换胶桶、换版、换机是事件，不是噪声。R2R 应在事件处重置或切模型，否则前馈用错斜率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：列扰动（厚度、开口率、机台 id）、列执行器、指定前馈模型与反馈残差。滤波：EWMA / Kalman 一类，本课不推公式，只要求延迟与方差进设计。与刻蚀偏置课一致：刻蚀前馈可动过刻，不把残差送给扫描机。限幅与解耦：多输入多输出时先配对（CD–剂量，overlay–网格）。</p><p><span class="marginnote">EWMA（指数加权滑动平均）就是「新数据占小头、旧均值占大头」的平均手段：权重取 \\(\\alpha = 0.2\\) 时，每次更新等于 0.2 份新测量加 0.8 份旧均值，单点噪声被压到约五分之一，代价是对真实突变的响应也慢下来——这正是 R2R 抗抖和跟得快之间的折衷旋钮。</span></p><p>前馈模型用工程实验片估斜率，并在保养后重估。R2R 文献把「事件」写成重置条件；本课要求事件列表进 MES（换胶、换版、换机、PM），而不是靠人记得去按重置。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前馈：\\(u = u_0 + K_\\mathrm{ff}(x_\\mathrm{up} - x_\\mathrm{nom})\\)。反馈：对 \\(y - T\\) 积分。两者加在设定上。若 \\(K_\\mathrm{ff}\\) 的模型与真实斜率不符，反馈会长期顶着一个偏置——看起来「反馈在工作」，其实前馈模型该修。事件检测把状态机从「跟踪」切到「重新辨识」。</p>',12)),(e(),n(i,null,{default:r(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E4%B8%8A%E6%B8%B8%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20FF%5B%22%E5%89%8D%E9%A6%88%22%5D%0A%20%20Y%5B%22%E6%9C%AC%E6%AD%A5%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20FB%5B%22%E5%8F%8D%E9%A6%88%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20FF%20--%3E%20U%5B%22%E8%AE%BE%E5%AE%9A%20u%22%5D%0A%20%20FB%20--%3E%20U%0A%20%20EVT%5B%22%E6%8D%A2%E7%89%88%20%2F%20%E4%BF%9D%E5%85%BB%22%5D%20--%3E%20RST%5B%22%E9%87%8D%E7%BD%AE%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>前馈与反馈加在同一执行器上时必须分层。事件重置切模型，避免换胶后的旧斜率把剂量拉飞。</p><p><span class="marginnote">数字实例：\\(K_\\mathrm{ff}\\) 就是「每 1 nm 胶厚偏差该改多少剂量」的斜率。若工艺实验测得胶厚每偏 1 nm 对应剂量 0.5 mJ/cm²，则 \\(K_\\mathrm{ff} = 0.5\\)；胶厚偏 +3 nm 就直接预加 1.5 mJ/cm²，完全不用等本层 CD 回来——斜率估错，这条前馈就成了新扰动源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>R2R 不替代 SPC 停机规则。不在本课写虚拟计量（后课）。不发明控制器专利细节。</p><p>后课默认：前馈吃已知扰动，反馈只吃残差，事件要重置。下一课抽样决定环的可观测性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前馈用上游量，反馈吃残差；二者必须分层以免抢旋钮。</li><li>R2R 节拍是批，必须含计量延迟。</li><li>事件切模型，不当成噪声滤掉。</li><li>出处：半导体 run-to-run 控制传统；SEMI R2R/APC 通称。</li></ul>',7))])}const C=B(p,[["render",A]]);export{c as __pageData,C as default};
